@startuml

class Factory {}

class Machine {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class Worker {
  + firstName : string
  + lastName : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class ProductType {
  + id : string
  + weight : float
}

class Material {
  + id : string
  + name : string
}

class Client {
  + id : string
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PurchaseOrder {
  + orderNumber : string
  + orderDate : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class OrderLine {
  + quantity : int
}

Factory "1" -- "*" Machine
Machine "1" -- "*" Worker
Machine "1" -- "*" ProductType
ProductType "*" -- "1" Material
Client "1" -- "*" PurchaseOrder
PurchaseOrder "1" *-- "*" OrderLine
OrderLine "*" -- "1" ProductType

@enduml

